126	 * @param {import('../plugin/contract.js').AgentRunInput} input
127	 * @returns {Promise<import('../plugin/contract.js').RunnerResult>}
128	 */
129	export async function runAgent(input) {
130	  const args = buildClaudeCodeCliArgs(input);
131	
132	  // spawnSync (not a shell string): the prompt is a plain argv element, so there is
133	  // no shell quoting/escaping to get wrong. Blocking is fine — the runner has
134	  // nothing else to do while the agent works. The sandbox-level timeout bounds it.
135	  const res = spawnSync('claude', args, {
136	    cwd: input.cwd,
137	    env: process.env,
138	    encoding: 'utf8',
139	    maxBuffer: 64 * 1024 * 1024,
140	  });
141	
142	  const stdout = res.stdout || '';
143	  const stderr = res.stderr || '';
144	  // Preserve the old concatenation order: stdout THEN stderr.
145	  const output = stdout + stderr;
146	  // spawnSync sets status=null + error when the binary can't be spawned at all.
147	  const agentExitCode = res.status == null ? -1 : res.status;
148	
149	  // Capture transcript + observed model regardless of success (the old adapter did
150	  // this even on the non-zero-exit path).
151	  const transcript = captureClaudeTranscript(input.cwd);
152	  const observedModel = extractObservedModelFromClaudeTranscript(transcript) ?? null;
153	
154	  if (res.error || agentExitCode !== 0) {
155	    // Mirror the old error string: last 5 lines of output, else a coded fallback.
156	    const errorLines = output.trim().split('\n').slice(-5).join('\n');
157	    const fallback = res.error
158	      ? `Failed to run claude: ${res.error.message}`
159	      : `Claude Code exited with code ${agentExitCode}`;
160	    return {
161	      ok: false,
162	      output,
163	      transcript,
164	      observedModel,
165	      error: errorLines || fallback,
166	      agentExitCode,
167	    };
168	  }
169	
170	  return { ok: true, output, transcript, observedModel, error: null, agentExitCode };
171	}
172	
173	/* ─────────────────────────── runnable (CLI) entry ─────────────────────────── */
174	
175	// True when this file is executed directly (`node run.mjs ...`), false when imported.
176	const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
177	
178	if (isMain) {
179	  // argv[2] is the AgentRunInput JSON (never contains secrets).
180	  const input = JSON.parse(process.argv[2]);
181	
182	  // Always produce a RunnerResult, even if the runner itself throws, so the host
183	  // always has a result file to read (node exit code stays 0 except on a truly
184	  // unrecoverable crash before we can write).
185	  let result;
186	  try {
187	    result = await runAgent(input);
188	  } catch (e) {
189	    result = {
190	      ok: false,
191	      output: '',
192	      transcript: null,
193	      observedModel: null,
194	      error: e && e.message ? e.message : String(e),
195	      agentExitCode: -1,
196	    };
197	  }
198	
199	  // Source of truth: the result file the host reads back via sandbox.readFile.
200	  try {
201	    mkdirSync(dirname(input.resultPath), { recursive: true });
202	    writeFileSync(input.resultPath, JSON.stringify(result));
203	  } catch {
204	    // If the file can't be written, the host falls back to the marker line below.
205	  }
206	
207	  // Fallback channel: a compact status line (no transcript — it can be huge).
208	  process.stdout.write(
209	    '__AGENT_RESULT__ ' +
210	      JSON.stringify({
211	        ok: result.ok,
212	        observedModel: result.observedModel,
213	        error: result.error,
214	        agentExitCode: result.agentExitCode,
215	      }) +
216	      '\n'
217	  );
218	
219	  // Exit 0: "the runner ran". Agent success/failure is conveyed via result.ok, not
220	  // the node exit code (the host distinguishes the two).
221	  process.exit(0);
222	}
